const exigir = (ok, mensaje) => [ok].filter(v => !v).forEach(() => { throw new Error(mensaje); });
const describir = (e) => [e?.httpCode && `HTTP ${e.httpCode}`, e?.message, e?.description]
  .filter(t => typeof t === 'string' && t).join(' - ').slice(0, 300) || 'error desconocido';
// OpenRouter responde el modelo sin prefijo de proveedor ("text-embedding-3-small" para "openai/text-embedding-3-small")
const mismoModelo = (respondido, configurado) =>
  [undefined, null].includes(respondido) || String(respondido).split('/').pop() === String(configurado).split('/').pop();

const cfg = $('Configuración RAG').first().json;
const r = $input.first().json;
exigir(!r.error, '[EMBEDDINGS] Falló el servicio de embeddings: ' + describir(r.error));
exigir(mismoModelo(r.model, cfg.modeloEmbeddings),
       `[EMBEDDINGS_CONTRATO] Se pidió ${cfg.modeloEmbeddings} y respondió ${r.model}`);
const vector = r.data?.[0]?.embedding;
exigir(Array.isArray(r.data) && r.data.length === 1 && Array.isArray(vector) && vector.length > 0 && vector.every(Number.isFinite),
       '[EMBEDDINGS_CONTRATO] El servicio de embeddings no devolvió un vector válido: ' + JSON.stringify(r).slice(0, 200));
exigir(vector.length === cfg.dimension, `[CONFIGURACION] El vector de la consulta tiene ${vector.length} dimensiones ` +
       `y la colección usa ${cfg.dimension} (NEXUS_EMBEDDING_DIMENSION)`);
return [{ json: { vector } }];
